CREATE TABLE policy_versions(org_id uuid PRIMARY KEY REFERENCES organizations(id), version integer NOT NULL DEFAULT 0);
CREATE TABLE policies(id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, rule jsonb NOT NULL, enabled boolean NOT NULL DEFAULT true, version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE executions(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations(id), request_id uuid NOT NULL, subject text NOT NULL, request_hash text NOT NULL, policy_version integer NOT NULL, decision text NOT NULL, status text NOT NULL, payload_cipher text, result_cipher text, token_hash text, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(org_id,request_id));
CREATE TABLE audit_entries(org_id uuid NOT NULL REFERENCES organizations(id), sequence bigint NOT NULL, kind text NOT NULL, metadata jsonb NOT NULL, created_at text NOT NULL, previous_hash text NOT NULL,entry_hash text NOT NULL,PRIMARY KEY(org_id,sequence));
ALTER TABLE policy_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE policy_versions FORCE ROW LEVEL SECURITY;
CREATE POLICY version_scope ON policy_versions USING(org_id::text=current_setting('app.org_id',true)) WITH CHECK(org_id::text=current_setting('app.org_id',true));
ALTER TABLE policies ENABLE ROW LEVEL SECURITY;
ALTER TABLE policies FORCE ROW LEVEL SECURITY;
CREATE POLICY policy_scope ON policies USING(org_id::text=current_setting('app.org_id',true)) WITH CHECK(org_id::text=current_setting('app.org_id',true));
ALTER TABLE executions ENABLE ROW LEVEL SECURITY;
ALTER TABLE executions FORCE ROW LEVEL SECURITY;
CREATE POLICY execution_scope ON executions USING(org_id::text=current_setting('app.org_id',true)) WITH CHECK(org_id::text=current_setting('app.org_id',true));
ALTER TABLE audit_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_entries FORCE ROW LEVEL SECURITY;
CREATE POLICY audit_scope ON audit_entries USING(org_id::text=current_setting('app.org_id',true)) WITH CHECK(org_id::text=current_setting('app.org_id',true));
REVOKE ALL ON policy_versions,policies,executions,audit_entries FROM PUBLIC;
GRANT SELECT,INSERT,UPDATE ON policy_versions,policies,executions TO devise_app;
GRANT SELECT,INSERT ON audit_entries TO devise_app;
CREATE INDEX policy_org ON policies(org_id,enabled);
CREATE INDEX execution_pending ON executions(org_id,status,expires_at);
